import secrets, time, hmac, hashlib

class SessionManager:
    def __init__(self, secret_key, ttl=3600, absolute=86400):
        self._secret = secret_key; self._ttl = ttl; self._absolute = absolute
        self._sessions = {}

    def create(self, user_id, data=None):
        sid = secrets.token_urlsafe(32); now = time.time()
        self._sessions[sid] = {'user_id': user_id, 'data': data or {},
            'created_at': now, 'last_active': now}
        return sid

    def validate(self, sid):
        s = self._sessions.get(sid)
        if not s: return None
        now = time.time()
        if now - s['created_at'] > self._absolute or now - s['last_active'] > self._ttl:
            self.destroy(sid); return None
        if now - s.get('last_rotated', s['created_at']) > 300: return self._rotate(sid)
        s['last_active'] = now; return s

    def _rotate(self, old):
        s = self._sessions.pop(old); new = secrets.token_urlsafe(32)
        s['last_rotated'] = time.time(); self._sessions[new] = s; return new

    def destroy_all(self, user_id):
        for k in [k for k,v in self._sessions.items() if v['user_id']==user_id]: del self._sessions[k]
```
256-bit IDs, dual timeout (idle+absolute), session rotation, bulk invalidation.

