import re, os
from pathlib import Path

class SecretScanner:
    RULES = {
        'aws_key': re.compile(r'AKIA[0-9A-Z]{16}'),
        'github': re.compile(r'gh[ps]_[A-Za-z0-9_]{36,}'),
        'private_key': re.compile(r'-----BEGIN.*PRIVATE KEY-----'),
        'generic': re.compile(r'(?i)(password|secret|token|api_key)\\s*[:=]\\s*["\'][^"\']{8,}["\']'),
        'jwt': re.compile(r'eyJ[A-Za-z0-9_-]{10,}\\.eyJ[A-Za-z0-9_-]{10,}\\.[A-Za-z0-9_-]{10,}'),
    }
    SKIP = {'.git', 'node_modules', '__pycache__', '.venv'}

    def scan(self, root):
        findings = []
        for f in Path(root).rglob('*'):
            if f.is_dir() or any(d in f.parts for d in self.SKIP): continue
            try: text = f.read_text(errors='ignore')
            except: continue
            for name, pat in self.RULES.items():
                for m in pat.finditer(text):
                    line = text[:m.start()].count('\n') + 1
                    findings.append({'file': str(f), 'line': line, 'rule': name, 'match': m.group()[:80]})
        return findings
```

