import queue, threading
from contextlib import contextmanager

class ConnectionPool:
    def __init__(self, factory, max_size=10):
        self._factory = factory; self._max = max_size
        self._pool = queue.Queue(maxsize=max_size); self._created = 0
        self._lock = threading.Lock()

    def _create(self):
        with self._lock:
            if self._created >= self._max: return None
            self._created += 1
        try: return self._factory()
        except: self._lock.acquire(); self._created -= 1; self._lock.release(); raise

    @contextmanager
    def acquire(self, timeout=30):
        conn = None
        try: conn = self._pool.get_nowait()
        except queue.Empty: pass
        if not conn: conn = self._create()
        if not conn: conn = self._pool.get(timeout=timeout)
        try: yield conn
        finally: self._pool.put(conn)
```
Context manager ensures return, lazy creation, max size enforcement, timeout on exhaustion.

