import logging, re

class SecureFormatter(logging.Formatter):
    SENSITIVE = {'password', 'token', 'secret', 'api_key', 'authorization'}
    INJECTION = [
        (re.compile(r'\x1b\[[0-9;]*m'), ''),
        (re.compile(r'[\x00-\x08\x0b\x0c\x0e-\x1f]'), ''),
        (re.compile(r'(\r\n|\n|\r)'), ' '),
    ]

    def format(self, record):
        msg = super().format(record)
        for key in self.SENSITIVE:
            msg = re.sub(rf'(?i){key}[^\s]{{0,5}}[=:]\s*["\']?([^"\'\s,}}\]]+)',
                f'{key}=***REDACTED***', msg)
        for pat, rep in self.INJECTION: msg = pat.sub(rep, msg)
        return msg[:10000]
```
Layers: sensitive data redaction, log injection prevention, size limiting.

