from html.parser import HTMLParser

class HTMLSanitizer(HTMLParser):
    ALLOWED = {'p', 'br', 'strong', 'em', 'a', 'ul', 'ol', 'li', 'code', 'pre'}
    DANGEROUS = {'script', 'style', 'iframe', 'object', 'embed', 'svg', 'math'}

    def __init__(self):
        super().__init__(); self._out = []; self._skip = False

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in self.DANGEROUS: self._skip = True; return
        if tag not in self.ALLOWED: return
        self._out.append(f'<{tag}>')

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in self.DANGEROUS: self._skip = False; return
        if tag in self.ALLOWED: self._out.append(f'</{tag}>')

    def handle_data(self, data):
        if not self._skip:
            self._out.append(data.replace('&', '&amp;').replace('<', '&lt;'))

    def sanitize(self, html):
        self._out = []; self._skip = False; self.feed(html)
        return ''.join(self._out)
```
Allowlist tags, strip dangerous (script/iframe/svg), escape content, validate URL attrs.
